export const envelope = [19, 25, 29];

export default function build(api) {
  const [W, H, D] = api.size;

  // Helper to place blocks safely within the envelope bounds
  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // Helpers to format stateful blocks reliably
  function getStair(stairBlock, facing, half = "bottom", shape = "straight") {
    const id = (stairBlock || "minecraft:spruce_stairs").split("[")[0];
    return `${id}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function getLog(logBlock, axis = "y") {
    const id = (logBlock || "minecraft:spruce_log").split("[")[0];
    return `${id}[axis=${axis}]`;
  }

  function getSlab(slabBlock, type = "bottom") {
    const id = (slabBlock || "minecraft:spruce_slab").split("[")[0];
    return `${id}[type=${type}]`;
  }

  function getTrapdoor(trapdoorBlock, facing = "north", half = "bottom", open = false) {
    const id = (trapdoorBlock || "minecraft:spruce_trapdoor").split("[")[0];
    return `${id}[facing=${facing},half=${half},open=${open}]`;
  }

  // World theme palette extraction
  const woodPlanks = api.theme.wood.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood.log || "minecraft:spruce_log";
  const woodStripped = api.theme.wood.stripped || api.theme.wood.log || "minecraft:stripped_spruce_log";
  const woodStairs = api.theme.wood.stairs || "minecraft:spruce_stairs";
  const woodSlab = api.theme.wood.slab || "minecraft:spruce_slab";
  const woodFence = api.theme.wood.fence || "minecraft:spruce_fence";
  const woodTrapdoor = api.theme.wood.trapdoor || "minecraft:spruce_trapdoor";

  const stonePrimary = api.theme.stone.primary || "minecraft:cobblestone";
  const stoneAccent = api.theme.stone.accent || "minecraft:mossy_cobblestone";
  const stoneStairs = api.theme.stone.stairs || "minecraft:cobblestone_stairs";
  const stoneSlab = api.theme.stone.slab || "minecraft:cobblestone_slab";
  const stoneWall = api.theme.stone.wall || "minecraft:cobblestone_wall";
  const groundPlinth = api.theme.ground.plinth || stonePrimary;

  const roofStairs = api.theme.roof.stairs || woodStairs;
  const roofSlab = api.theme.roof.slab || woodSlab;
  const roofSolid = api.theme.roof.solid || woodPlanks;

  const seatY = 4; // Node-local Y of the main floor / ground meeting plane

  // =========================================================================
  // 1. FOUNDATION & TERRAIN CONFORMANCE (Rule 6)
  // =========================================================================
  // Every column under the footprint builds down to meet the local terrain.
  for (let x = 1; x <= 17; x++) {
    for (let z = 0; z <= 28; z++) {
      const isFootprint = (x >= 2 && x <= 16 && z >= 1 && z <= 27) ||
                          (x >= 6 && x <= 12 && (z === 0 || z === 28));

      if (isFootprint) {
        const terrainH = Math.round(api.heightAt(x, z));
        const colBaseY = Math.max(0, Math.min(seatY, seatY + terrainH));

        for (let y = colBaseY; y <= seatY; y++) {
          const isPerimeter = (x === 2 || x === 16 || z === 1 || z === 27);
          const stoneMat = ((x + y + z) % 5 === 0) ? stoneAccent : groundPlinth;
          set(x, y, z, isPerimeter ? stoneMat : stonePrimary);
        }
      }
    }
  }

  // Front entrance stairs stepping down to terrain at z=0 (x=8..10)
  for (let x = 8; x <= 10; x++) {
    const frontH = Math.max(0, Math.min(seatY, seatY + Math.round(api.heightAt(x, 0))));
    for (let y = frontH; y < seatY; y++) {
      set(x, y, 0, getStair(stoneStairs, "south", "bottom"));
    }
  }

  // =========================================================================
  // 2. MAIN FLOOR & CENTRAL HEARTH (y = 4)
  // =========================================================================
  for (let x = 3; x <= 15; x++) {
    for (let z = 2; z <= 26; z++) {
      if (x === 3 || x === 15 || z === 2 || z === 26) {
        set(x, seatY, z, getLog(woodLog, "y"));
      } else if (x === 9 && z >= 6 && z <= 22) {
        // Central long hearth channel
        if (z >= 13 && z <= 15) {
          set(x, seatY, z, "minecraft:campfire[facing=north,lit=true]");
        } else {
          set(x, seatY, z, stonePrimary);
        }
      } else if ((x === 8 || x === 10) && z >= 6 && z <= 22) {
        const facing = (x === 8) ? "east" : "west";
        set(x, seatY, z, getStair(stoneStairs, facing, "bottom"));
      } else {
        set(x, seatY, z, woodPlanks);
      }
    }
  }

  // =========================================================================
  // 3. WALLS & EXTERIOR BUTTRESSES (y = 5 to 9)
  // =========================================================================
  const pillarZ = [2, 6, 10, 14, 18, 22, 26];

  // Side walls (x = 3 and x = 15)
  for (let z = 2; z <= 26; z++) {
    for (const wx of [3, 15]) {
      const isPillar = pillarZ.includes(z);
      if (isPillar) {
        for (let y = 5; y <= 9; y++) {
          set(wx, y, z, getLog(woodLog, "y"));
        }
      } else {
        set(wx, 5, z, getLog(woodLog, "z"));
        set(wx, 6, z, woodStripped);
        // Slit embrasure windows at panel centers
        if ((z % 4 === 0) || (z % 4 === 1)) {
          set(wx, 7, z, "minecraft:iron_bars");
        } else {
          set(wx, 7, z, woodPlanks);
        }
        set(wx, 8, z, woodStripped);
        set(wx, 9, z, getLog(woodLog, "z")); // Wall plate beam
      }
    }
  }

  // Exterior raking buttress stanchions (x = 2 and x = 16)
  for (const bz of [4, 8, 12, 16, 20, 24]) {
    for (const [bx, facing, lean] of [[2, "east", "west"], [16, "west", "east"]]) {
      set(bx, 5, bz, getLog(woodLog, "y"));
      set(bx, 6, bz, getStair(woodStairs, facing, "bottom"));
      set(bx, 7, bz, woodFence);
      set(bx, 8, bz, getStair(woodStairs, lean, "top"));
    }
  }

  // Front Portal Wall (North, z = 2)
  for (let x = 4; x <= 14; x++) {
    for (let y = 5; y <= 9; y++) {
      if (x >= 8 && x <= 10 && y <= 7) {
        // Grand open entrance portal
        continue;
      }
      if (x === 7 || x === 11) {
        set(x, y, 2, getLog(woodLog, "y"));
      } else {
        set(x, y, 2, woodStripped);
      }
    }
  }
  // Portal carved timber arch lintel at z = 2
  set(8, 7, 2, getStair(woodStairs, "east", "top"));
  set(9, 7, 2, getLog(woodStripped, "x"));
  set(10, 7, 2, getStair(woodStairs, "west", "top"));
  set(9, 8, 2, woodPlanks);

  // Rear Wall (South, z = 26)
  for (let x = 4; x <= 14; x++) {
    for (let y = 5; y <= 9; y++) {
      if (x === 9 && y === 7) {
        set(x, y, 26, "minecraft:iron_bars"); // High carved slit
      } else if (x === 7 || x === 11) {
        set(x, y, 26, getLog(woodLog, "y"));
      } else {
        set(x, y, 26, woodStripped);
      }
    }
  }

  // Front entrance porch & iron braziers (z = 0..1)
  set(7, 5, 1, getLog(woodLog, "y"));
  set(7, 6, 1, getLog(woodLog, "y"));
  set(11, 5, 1, getLog(woodLog, "y"));
  set(11, 6, 1, getLog(woodLog, "y"));
  for (let x = 7; x <= 11; x++) {
    set(x, 7, 1, getLog(woodLog, "x"));
  }
  set(8, 8, 1, getStair(roofStairs, "east", "bottom"));
  set(9, 8, 1, roofSolid);
  set(10, 8, 1, getStair(roofStairs, "west", "bottom"));
  set(9, 9, 1, roofSolid);
  set(9, 6, 1, "minecraft:lantern[hanging=true]");

  // Flanking Iron Braziers (z = 0, x = 6 and x = 12)
  for (const bx of [6, 12]) {
    set(bx, 5, 0, stoneWall);
    set(bx, 6, 0, "minecraft:iron_bars");
    set(bx, 7, 0, "minecraft:campfire[facing=north,lit=true]");
  }

  // =========================================================================
  // 4. INTERIOR AISLE POSTS & RAFTER TIES (y = 5 to 11)
  // =========================================================================
  for (const iz of [6, 10, 14, 18, 22]) {
    for (const ix of [6, 12]) {
      for (let y = 5; y <= 10; y++) {
        set(ix, y, iz, getLog(woodLog, "y"));
      }
      // Longitudinal arcade plate
      set(ix, 11, iz, getLog(woodLog, "z"));
    }
    // Transverse tie beam across the central nave
    for (let x = 7; x <= 11; x++) {
      set(x, 10, iz, getLog(woodLog, "x"));
    }
    set(7, 9, iz, getStair(woodStairs, "east", "top"));
    set(11, 9, iz, getStair(woodStairs, "west", "top"));
    // King post up to roof ridge
    for (let y = 11; y <= 18; y++) {
      set(9, y, iz, getLog(woodLog, "y"));
    }
  }

  // =========================================================================
  // 5. STEEP HIGH-PEAKED ROOF (y = 8 to 20, z = 1 to 27)
  // =========================================================================
  // Profile coordinates: dx from center line (x=9) mapped to Y elevation
  // dx = 8: y = 8 (eaves)
  // dx = 7: y = 9
  // dx = 6: y = 11
  // dx = 5: y = 12
  // dx = 4: y = 14
  // dx = 3: y = 15
  // dx = 2: y = 17
  // dx = 1: y = 18
  // dx = 0: y = 19 (ridge)

  for (let z = 1; z <= 27; z++) {
    const isOverhang = (z === 1 || z === 27);
    const isSmokeVent = (z >= 13 && z <= 15);

    for (let dx = 0; dx <= 8; dx++) {
      if (dx === 0) {
        // Ridge line
        if (isSmokeVent) {
          // Open smoke vent with raised clerestory cap
          set(9, 18, z, woodPlanks);
          set(9, 20, z, getSlab(roofSlab, "bottom"));
          if (z === 13 || z === 15) {
            set(9, 19, z, woodFence);
          }
        } else {
          set(9, 18, z, roofSolid);
          set(9, 19, z, getLog(woodLog, "z"));
          // Snow capping along the ridge
          if (api.random() < 0.65) {
            set(9, 20, z, "minecraft:snow[layers=1]");
          }
        }
      } else {
        const xL = 9 - dx;
        const xR = 9 + dx;

        let stairY = 8;
        let solidY = 7;
        let supportY = 0;

        if (dx === 8) {
          stairY = 8;
          solidY = 0;
          supportY = 7;
        } else if (dx === 7) {
          stairY = 9;
          solidY = 8;
          supportY = 8;
        } else if (dx === 6) {
          stairY = 11;
          solidY = 10;
          supportY = 10;
        } else if (dx === 5) {
          stairY = 12;
          solidY = 11;
          supportY = 11;
        } else if (dx === 4) {
          stairY = 14;
          solidY = 13;
          supportY = 13;
        } else if (dx === 3) {
          stairY = 15;
          solidY = 14;
          supportY = 14;
        } else if (dx === 2) {
          stairY = 17;
          solidY = 16;
          supportY = 16;
        } else if (dx === 1) {
          stairY = 18;
          solidY = 17;
          supportY = 17;
        }

        // Left flank (facing west)
        if (solidY > 0) set(xL, solidY, z, roofSolid);
        set(xL, stairY, z, getStair(roofStairs, "west", "bottom"));
        if (supportY > 0) set(xL, supportY, z, getStair(woodStairs, "east", "top"));

        // Right flank (facing east)
        if (solidY > 0) set(xR, solidY, z, roofSolid);
        set(xR, stairY, z, getStair(roofStairs, "east", "bottom"));
        if (supportY > 0) set(xR, supportY, z, getStair(woodStairs, "west", "top"));

        // Winter snow accumulation on upper roof slope
        if (dx <= 4 && !isOverhang && api.random() < 0.7) {
          set(xL, stairY + 1, z, "minecraft:snow[layers=1]");
          set(xR, stairY + 1, z, "minecraft:snow[layers=1]");
        }
      }
    }
  }

  // =========================================================================
  // 6. GABLE TRIANGULAR WALL INFILLS (z = 2 and z = 26)
  // =========================================================================
  for (const gz of [2, 26]) {
    for (let x = 4; x <= 14; x++) {
      const dx = Math.abs(x - 9);
      let maxY = 18;
      if (dx === 5) maxY = 11;
      else if (dx === 4) maxY = 13;
      else if (dx === 3) maxY = 14;
      else if (dx === 2) maxY = 16;
      else if (dx === 1) maxY = 17;
      else if (dx === 0) maxY = 18;

      for (let y = 10; y <= maxY; y++) {
        if (dx === 0 && (y === 13 || y === 14)) {
          set(x, y, gz, woodFence); // Carved gable runic opening
        } else {
          set(x, y, gz, (y % 2 === 0) ? woodStripped : woodPlanks);
        }
      }
    }
  }

  // =========================================================================
  // 7. CARVED DRAGONHEAD GABLE PROWS (North at z=0..1, South at z=27..28)
  // =========================================================================
  // North Dragonhead (Front Gable Prow facing North, -Z)
  set(9, 19, 1, getLog(woodLog, "z"));
  set(9, 20, 1, getLog(woodLog, "y"));
  set(9, 21, 1, getLog(woodLog, "y"));
  set(9, 22, 1, getStair(woodStairs, "south", "bottom")); // Crest curve
  set(9, 20, 0, getStair(woodStairs, "north", "top"));    // Throat
  set(9, 21, 0, getLog(woodLog, "y"));                   // Jaw
  set(9, 22, 0, getStair(woodStairs, "north", "bottom")); // Snout
  set(9, 23, 0, woodFence);                              // Horn

  // South Dragonhead (Rear Gable Prow facing South, +Z)
  set(9, 19, 27, getLog(woodLog, "z"));
  set(9, 20, 27, getLog(woodLog, "y"));
  set(9, 21, 27, getLog(woodLog, "y"));
  set(9, 22, 27, getStair(woodStairs, "north", "bottom")); // Crest curve
  set(9, 20, 28, getStair(woodStairs, "south", "top"));    // Throat
  set(9, 21, 28, getLog(woodLog, "y"));                   // Jaw
  set(9, 22, 28, getStair(woodStairs, "south", "bottom")); // Snout
  set(9, 23, 28, woodFence);                              // Horn

  return {
    name: "Great Mead Hall",
    seatY: seatY,
    anchors: {
      front: [9, seatY, 0],
      door: [9, seatY + 1, 2]
    },
    interiors: [
      {
        min: [4, seatY + 1, 3],
        max: [14, seatY + 7, 25],
        kind: "hall"
      }
    ]
  };
}
